def format_currency(n):
    """
    Format a number as a currency string with $ sign and commas.
    For negative numbers, the minus sign comes before the dollar sign.

    Example:
        4640039 -> "$4,640,039"
        -4640039 -> "-$4,640,039"
    """
    if n < 0:
        return "-$" + format(-n, ',')
    else:
        return "$" + format(n, ',')
